package io.github.hemanthvk980.shortener.domain;

import jakarta.persistence.*;
import java.time.Instant;

@Entity
@Table(name = "link")
public class Link {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, unique = true, length = 16)
    private String code;

    @Column(name = "target_url", nullable = false, length = 2048)
    private String targetUrl;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    @Column(name = "click_count", nullable = false)
    private long clickCount;

    protected Link() {}

    public Link(String code, String targetUrl, Instant createdAt) {
        this.code = code;
        this.targetUrl = targetUrl;
        this.createdAt = createdAt;
    }

    public Long getId() { return id; }
    public String getCode() { return code; }
    public String getTargetUrl() { return targetUrl; }
    public Instant getCreatedAt() { return createdAt; }
    public long getClickCount() { return clickCount; }
}

package io.github.hemanthvk980.shortener.domain;

import jakarta.persistence.*;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;

@Entity
@Table(name = "click_event")
public class ClickEvent {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "link_id", nullable = false)
    private Long linkId;

    @Column(name = "clicked_at", nullable = false)
    private Instant clickedAt;

    @Column(name = "click_date", nullable = false)
    private LocalDate clickDate;

    protected ClickEvent() {}

    public ClickEvent(Long linkId, Instant clickedAt) {
        this.linkId = linkId;
        this.clickedAt = clickedAt;
        this.clickDate = LocalDate.ofInstant(clickedAt, ZoneOffset.UTC);
    }
}

package io.github.hemanthvk980.shortener.repo;

import io.github.hemanthvk980.shortener.domain.Link;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;

public interface LinkRepository extends JpaRepository<Link, Long> {
    Optional<Link> findByCode(String code);

    boolean existsByCode(String code);

    @Modifying
    @Query("update Link l set l.clickCount = l.clickCount + 1 where l.id = :id")
    int incrementClicks(Long id);
}

package io.github.hemanthvk980.shortener.repo;

import io.github.hemanthvk980.shortener.domain.ClickEvent;
import java.time.LocalDate;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface ClickEventRepository extends JpaRepository<ClickEvent, Long> {
    interface Daily { LocalDate getClickDate(); long getClicks(); }

    @Query("select c.clickDate as clickDate, count(c) as clicks from ClickEvent c where c.linkId = :linkId and c.clickDate >= :since group by c.clickDate order by c.clickDate")
    List<Daily> countByDay(Long linkId, LocalDate since);
}

CREATE TABLE link (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code        VARCHAR(16)   NOT NULL UNIQUE,
    target_url  VARCHAR(2048) NOT NULL,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    click_count BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE click_event (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    link_id    BIGINT NOT NULL REFERENCES link (id),
    clicked_at TIMESTAMP WITH TIME ZONE NOT NULL,
    click_date DATE NOT NULL
);

CREATE INDEX ix_click_event_link_date ON click_event (link_id, click_date);
